/**
 * @brief To get current time in ms
 * @return current time in ms
 */
uint64_t
app_gen_n_get_time_ms(void)
{
  struct timespec ts;
  clock_gettime(CLOCK_REALTIME, &ts);
  return (uint64_t)(ts.tv_sec * 1000LL + ts.tv_nsec / 1000000);
}

static struct gen_con_record_data con_record_data[CONFIG_CONNECT_RECORD_MAX_NUM];
// Notes: DO NOT use this index anywhere else directly please.
static uint32_t g_con_idx;
/**
 * @brief To allocate an unique index of con_record_data
 * @return An allocated index
 * notes make sure g_con_idx was init to 0 before using it.
 */
uint32_t
app_pro_gen_get_idx(void)
{
  return (g_con_idx < CONFIG_CONNECT_RECORD_MAX_NUM) ? (g_con_idx++) : (CONFIG_CONNECT_RECORD_MAX_NUM - 1);
}
