#define SKF_HCI_REQ_DIR \
  "/run/skf-gateway/hci-conn-update/requests"
 
#define SKF_HCI_RES_DIR \
  "/run/skf-gateway/hci-conn-update/results"
 
 
static app_state_t
request_privileged_hci_update(
  const struct bluetooth_connection_param *con_param,
  const uint8_t con_id[6])
{
  static unsigned long request_seq = 0;
 
  char token[96];
  char tmp_path[256];
  char req_path[256];
  char result_path[256];
  char payload[256];
 
  struct timespec ts;
 
  int fd;
  int payload_len;
  int result_rc;
 
  unsigned long seq;
 
  if((con_param == NULL) ||
     (con_id == NULL))
  {
    DBG_LOG_ERR("PRIV_HCI invalid parameters");
    return ST_ERR;
  }
 
  /*
   * Multiple PredictSensor connections can reach here concurrently.
   * Generate an individual request name for every invocation.
   */
  seq = __sync_add_and_fetch(
&request_seq,
          1);
 
  clock_gettime(
    CLOCK_MONOTONIC,
&ts);
 
  snprintf(
    token,
    sizeof(token),
    "%ld-%ld-%09ld-%lu",
    (long)getpid(),
    (long)ts.tv_sec,
    (long)ts.tv_nsec,
    seq);
 
  snprintf(
    tmp_path,
    sizeof(tmp_path),
    "%s/%s.tmp",
    SKF_HCI_REQ_DIR,
    token);
 
  snprintf(
    req_path,
    sizeof(req_path),
    "%s/%s.req",
    SKF_HCI_REQ_DIR,
    token);
 
  snprintf(
    result_path,
    sizeof(result_path),
    "%s/%s.result",
    SKF_HCI_RES_DIR,
    token);
 
  /*
   * Request format:
   *
   * MAC PHY MIN MAX LAT SUP MINCE MAXCE
   */
  payload_len = snprintf(
    payload,
    sizeof(payload),
    "%02X%02X%02X%02X%02X%02X "
    "%u %u %u %u %u %u %u\n",
 
    con_id[0],
    con_id[1],
    con_id[2],
    con_id[3],
    con_id[4],
    con_id[5],
 
    (unsigned int)con_param->phy,
    (unsigned int)con_param->min_con_interval,
    (unsigned int)con_param->max_con_interval,
    (unsigned int)con_param->con_latency,
    (unsigned int)con_param->supervision_timeout,
    (unsigned int)con_param->min_ce_len,
    (unsigned int)con_param->max_ce_len);
 
  if((payload_len <= 0) ||
     ((size_t)payload_len >= sizeof(payload)))
  {
    DBG_LOG_ERR(
      "PRIV_HCI request payload overflow");
 
    return ST_ERR;
  }
 
  fd = open(
    tmp_path,
    O_WRONLY |
    O_CREAT |
    O_EXCL |
    O_CLOEXEC,
    0600);
 
  if(fd < 0)
  {
    DBG_LOG_ERR(
      "PRIV_HCI request open failed: %s",
      strerror(errno));
 
    return ST_ERR;
  }
 
  ssize_t written =
    write(
      fd,
      payload,
      (size_t)payload_len);
 
  if(written != payload_len)
  {
    DBG_LOG_ERR(
      "PRIV_HCI request write failed: %s",
      strerror(errno));
 
    close(fd);
    unlink(tmp_path);
 
    return ST_ERR;
  }
 
  fsync(fd);
  close(fd);
 
  /*
   * Publish atomically so the systemd path watcher never sees
   * a partially written request.
   */
  if(rename(
       tmp_path,
       req_path) != 0)
  {
    DBG_LOG_ERR(
      "PRIV_HCI request publish failed: %s",
      strerror(errno));
 
    unlink(tmp_path);
 
    return ST_ERR;
  }
 
  /*
   * Original bt_hcitool_set_bluetooth_connection_param()
   * was synchronous.
   *
   * Keep equivalent semantics:
   * wait until the root helper has executed the request.
   *
   * 60 * 100 ms = maximum 6 seconds.
   */
  for(int retry = 0;
      retry < 60;
      retry++)
  {
    FILE *fp =
      fopen(
        result_path,
        "r");
 
    if(fp != NULL)
    {
      result_rc = -1;
 
      if(fscanf(
           fp,
           "%d",
&result_rc) == 1)
      {
        fclose(fp);
 
        unlink(
          result_path);
 
        if(result_rc == 0)
        {
          DBG_LOG_INFO(
            "PRIV_HCI_CONN_UPDATE_OK");
 
          return ST_OK;
        }
 
        DBG_LOG_ERR(
          "PRIV_HCI_CONN_UPDATE_FAILED rc:%d",
          result_rc);
 
        return ST_ERR;
      }
 
      fclose(fp);
    }
 
    usleep(100000);
  }
 
  /*
   * Never leave a stale request that might execute later
   * against another BLE connection.
   */
  unlink(req_path);
 
  DBG_LOG_ERR(
    "PRIV_HCI_CONN_UPDATE_TIMEOUT");
 
  return ST_ERR;
}
